# the principle before the first amortizing question: an animated schedule of ״ניר״ (the bond of question 3), built click by click
def _amort_chart():
    bal = [200, 200, 200, 200, 150, 100, 50]
    cpn = [8, 8, 8, 8, 6, 4, 2]
    tot = [8, 8, 8, 58, 56, 54, 52]
    X = lambda t: 70 + t * 86
    y0, k = 318, 0.9
    p = [f'<line x1="30" y1="{y0}" x2="700" y2="{y0}" stroke="#1b2d55" stroke-width="2.6"/><polygon points="708,{y0} 696,{y0 - 6} 696,{y0 + 6}" fill="#1b2d55"/>']
    p += [f'<line x1="{X(t)}" y1="{y0 - 5}" x2="{X(t)}" y2="{y0 + 5}" stroke="#1b2d55" stroke-width="2"/>' + T(X(t), y0 + 22, f'{t}', 16) for t in range(8)]
    p.append(T(X(0), y0 + 42, 'שנה', 16, '#5d6a86', 500))
    p.append(GS(1, T(20, 26, 'יתרת ערך נקוב בתחילת השנה', 15, '#27447f', 700, 'start')
               + ''.join(f'<rect class="bar" x="{X(t + 1) - 24}" y="{y0 - b * k:.1f}" width="48" height="{b * k:.1f}" rx="6" fill="#c8d4f2" stroke="#27447f" stroke-width="1.6"/>'
                         + T(X(t + 1), y0 - b * k / 2 + 6, b, 15, '#1b2d55', 700) for t, b in enumerate(bal)), 'grow'))
    for t, c in enumerate(cpn):
        p.append(GS(2, BADGE(X(t + 1), y0 - bal[t] * k - 12, c, '#0f9d90', fs=15), 'pop', .08 * t))
    for t in range(3, 7):
        x, top = X(t + 1) + 34, y0 - bal[t] * k
        p.append(GS(3, ARW(x, top + 4, x, top + 50 * k - 2, '#ff6a4d', 3) + T(x + 2, top + 50 * k / 2 + 5, '50', 16, '#c4421f', 800, 'start'), 'draw', .15 * (t - 3)))
    p.append(GS(4, T(X(0), y0 + 72, 'סך תשלום', 16, '#16213a', 700), 'fade'))
    for t, s in enumerate(tot):
        p.append(GS(4, BADGE(X(t + 1), y0 + 72, s, '#1b2d55', fs=15), 'pop', .08 * t))
    p.append(GS(5, ARW(X(7), y0 + 92, X(0) + 4, y0 + 92, '#ff6a4d', 3, curve=34) + BADGE(X(0) + 6, y0 + 140, 'NPV: 209.97', '#ff6a4d', fs=15), 'draw'))
    return DIAG(''.join(p), 720, 470, 'לוח סילוקין של ״ניר״: יתרה, קופון, פירעון וסך תשלום')


